import glob
import os
import re
import subprocess
import sys

BINARY = "/app/admin-tool"
OUTPUT = "/app/output.txt"
SOURCE_CANDIDATES = [
    "/app/main.go",
    "/app/main.  go",
    "/app/main. go",
    "/app/main.go ",
]


def find_source():
    for p in SOURCE_CANDIDATES:
        if os.path.isfile(p):
            return p
    # glob fallback: any .go under /app (handles odd spacing in filename)
    for p in sorted(glob.glob("/app/*.go") + glob.glob("/app/*.go ") + glob.glob("/app/main*go*")):
        if os.path.isfile(p):
            return p
    # last resort: any file in /app containing 'package main' and 'flag'
    try:
        for name in os.listdir("/app"):
            fp = os.path.join("/app", name)
            if os.path.isfile(fp):
                try:
                    with open(fp, "r", errors="ignore") as f:
                        head = f.read(4096)
                    if "package main" in head and "flag" in head:
                        return fp
                except OSError:
                    continue
    except OSError:
        pass
    return None


def parse_go_int(tok):
    t = tok.strip()
    # unwrap byte(...) / uint8(...)
    m = re.match(r"^(?:byte|uint8|rune|int32|int)\s*\(\s*(.*)\s*\)$", t, re.DOTALL)
    if m:
        t = m.group(1).strip()
    # char literal 'x' with escapes
    if len(t) >= 2 and t[0] == "'" and t[-1] == "'":
        inner = t[1:-1]
        inner = inner.replace("_", "")
        if inner.startswith("\\"):
            esc = inner[1:]
            if esc == "n":
                return 10
            if esc == "t":
                return 9
            if esc == "r":
                return 13
            if esc == "0":
                return 0
            if esc == "\\":
                return 92
            if esc == "'":
                return 39
            if esc == '"':
                return 34
            if esc.startswith("x") and len(esc) == 3:
                return int(esc[1:], 16)
            if esc.startswith("u") or esc.startswith("U"):
                return ord(inner.encode("utf-8", "ignore")[:1] or b"?")
            return ord(esc[0])
        return ord(inner[0])
    t = t.replace("_", "")
    try:
        if t.lower().startswith("0x"):
            return int(t, 16)
        if t.lower().startswith("0o"):
            return int(t, 8)
        if t.lower().startswith("0b"):
            return int(t, 2)
        if len(t) > 1 and t.startswith("0") and t[1:].isdigit():
            # Go legacy octal
            return int(t, 8)
        return int(t, 0)
    except ValueError:
        return None


def parse_byte_list(inner):
    vals = []
    for part in inner.split(","):
        p = part.strip()
        if not p:
            continue
        # skip comments
        p = p.split("//")[0].strip()
        if not p:
            continue
        v = parse_go_int(p)
        if v is None:
            return None
        vals.append(v & 0xFF)
    return bytes(vals) if vals else None


def unescape_go_str(inner):
    out = bytearray()
    i = 0
    while i < len(inner):
        c = inner[i]
        if c != "\\":
            out.extend(c.encode("utf-8"))
            i += 1
            continue
        i += 1
        if i >= len(inner):
            break
        e = inner[i]
        if e == "n":
            out.append(10)
        elif e == "t":
            out.append(9)
        elif e == "r":
            out.append(13)
        elif e == "\\":
            out.append(92)
        elif e == '"':
            out.append(34)
        elif e == "'":
            out.append(39)
        elif e == "x" and i + 2 < len(inner):
            try:
                out.append(int(inner[i + 1:i + 3], 16))
            except ValueError:
                pass
            i += 2
        elif e == "u" and i + 4 < len(inner):
            try:
                out.extend(chr(int(inner[i + 1:i + 5], 16)).encode("utf-8"))
            except ValueError:
                pass
            i += 4
        elif e == "U" and i + 8 < len(inner):
            try:
                out.extend(chr(int(inner[i + 1:i + 9], 16)).encode("utf-8"))
            except ValueError:
                pass
            i += 8
        elif e.isdigit():
            # octal escape \ooo
            j = i
            dig = ""
            while j < len(inner) and len(dig) < 3 and inner[j] in "01234567":
                dig += inner[j]
                j += 1
            try:
                out.append(int(dig, 8) & 0xFF)
            except ValueError:
                pass
            i = j - 1
        else:
            out.extend(e.encode("utf-8"))
        i += 1
    return bytes(out)


def is_plausible(s):
    if not isinstance(s, str) or not (1 <= len(s) <= 256):
        return False
    if any(ord(c) < 32 or ord(c) == 127 for c in s):
        return False
    # require mostly printable without weird control; at least 2 alnum
    al = sum(1 for c in s if c.isalnum())
    return al >= 2


def looks_like_cred(s):
    if not is_plausible(s):
        return False
    if not (3 <= len(s) <= 128):
        return False
    return True


def var_hint(name):
    n = (name or "").lower()
    if any(k in n for k in ("user", "name", "login", "admin", "account", "uname")):
        return "user"
    if any(k in n for k in ("pass", "pwd", "passwd", "secret", "pw")):
        return "pass"
    return None


