    """Return list of dicts {var, data(bytes), pos} for []byte{...} literals."""
    arrs = []
    # []byte{...} and []uint8{...} (allow spaces inside brackets)
    pat = re.compile(r"\[\s*\]\s*(?:byte|uint8)\s*\{\s*([^}]*)\}", re.DOTALL)
    for m in pat.finditer(src):
