        prefix = src[line_start:start]
        mm = re.search(r"(\w+)\s*:?=\s*[^\n]*$", prefix.strip())
        vm = mm.group(1) if mm else ""
        # avoid double counting same position
        if any(abs(a["pos"] - start) < 4 for a in arrs):
            continue
        arrs.append({"var": vm or "", "data": data, "pos": start})
    return arrs


